// frontend/lib/utils/images.ts
// Generic blur placeholder (a tiny gray blurred square)
export const blurDataURL = 'data:image/jpeg;base64,'

// Helper function for image props
export function getImageProps(src: string, alt: string) {
  return {
    src,
    alt,
    placeholder: 'blur' as const,
    blurDataURL,
    sizes: '(max-width: 768px) 100vw, (max-width: 1200px) 50vw, 33vw'
  }
}